@pure
fn parseChecked(raw: Text) -> Int {
    let n: Int = 0;
    let code: Int = 0;
    val(raw, n, code);
    if code != 0 {
        ret -1;
    }
    ret n;
}
fn main() -> Void {
    let fields: Text[] = ["42", "7x", "", "-13", "100", "3.5"];
    let good: Int = 0;
    let bad: Int = 0;
    let total: Int = 0;
    loop i in 0..length(fields) {
        let v: Int = parseChecked(fields[i]);
        if v == -1 {
            bad = bad + 1;
            fx { println("reject: ", fields[i]); }
        } else {
            good = good + 1;
            total = total + v;
        }
    }
    fx {
        println("accepted=", good, " rejected=", bad);
        println("sum=", total);
    }
}

type Shard { total: Int = 0; count: Int = 0; }

fn tallyRange(s: Shard, lo: Int, hi: Int) -> Void {
    loop i in lo..hi {
        if i % 3 == 0 {
            s.total = s.total + i;
            s.count = s.count + 1;
        }
    }
    ret;
}

fn main() -> Void {
    let a: Shard = new Shard { total: 0, count: 0 };
    let b: Shard = new Shard { total: 0, count: 0 };
    par {
        tallyRange(a, 0, 25);
        tallyRange(b, 25, 50);
    }
    let total: Int = a.total + b.total;
    let count: Int = a.count + b.count;
    fx {
        println("shardA total=", a.total, " count=", a.count);
        println("shardB total=", b.total, " count=", b.count);
        println("combined total=", total, " count=", count);
    }
}

fn main() -> Void {
    let f: File;
    let path: Text = "ledger_tmp.txt";
    fx {
        assign(f, path);
        rewrite(f);
        writeln(f, "alpha,10");
        writeln(f, "beta,25");
        writeln(f, "gamma,7");
        close(f);
    }
    let names: Text[] = [];
    let vals: Int[] = [];
    fx {
        assign(f, path);
        reset(f);
        loop i in 0..3 {
            let line: Text = "";
            readln(f, line);
            let comma: Int = pos(",", line);
            let nm: Text = line[0..comma];
            let rest: Text = line[comma + 1..string_len(line)];
            names = names + [nm];
            vals = vals + [parse_int(rest)];
        }
        close(f);
        erase(f);
    }
    let total: Int = 0;
    loop i in 0..length(vals) { total = total + vals[i]; }
    fx {
        loop i in 0..length(names) { println(names[i], "=", vals[i]); }
        println("total=", total);
    }
}

@pure
fn allPositive(xs: Int[]) -> Bool {
    loop i in 0..length(xs) {
        if xs[i] <= 0 { ret false; }
    }
    ret true;
}
@pre allPositive(xs)
@post result >= 0
@pure
fn spread(xs: Int[]) -> Int {
    let lo: Int = xs[0];
    let hi: Int = xs[0];
    loop i in 1..length(xs) {
        if xs[i] < lo { lo = xs[i]; }
        if xs[i] > hi { hi = xs[i]; }
    }
    ret hi - lo;
}
fn main() -> Void {
    let a: Int[] = [4, 19, 7, 2, 11];
    fx { println("spread=", spread(a)); }
    let b: Int[] = [5];
    fx { println("single=", spread(b)); }
}

@pure
fn evens(xs: Int[]) -> Int[] {
    let out: Int[] = [];
    loop i in 0..length(xs) { if xs[i] % 2 == 0 { out = out + [xs[i]]; } }
    ret out;
}
@pure
fn odds(xs: Int[]) -> Int[] {
    let out: Int[] = [];
    loop i in 0..length(xs) { if xs[i] % 2 != 0 { out = out + [xs[i]]; } }
    ret out;
}
fn main() -> Void {
    let src: Int[] = [5, 2, 9, 4, 7, 6];
    let merged: Int[] = evens(src) + [0] + odds(src) + [99];
    fx {
        print("merged:");
        loop i in 0..length(merged) { print(" ", merged[i]); }
        println("");
        println("len=", length(merged));
    }
}

type Counter {
    hits: Int = 0;
    label: Text = "";
    fn bump(amount: Int) -> Void {
        self.hits = self.hits + amount;
        ret;
    }
    fn describe(prefix: Text) -> Text {
        ret prefix + self.label + "=" + int_to_text(self.hits);
    }
}
fn main() -> Void {
    let c: Counter = new Counter { hits: 0, label: "clicks" };
    let weights: Int[] = [3, 1, 4, 1, 5];
    loop i in 0..length(weights) {
        c.bump(weights[i]);
    }
    fx {
        println(c.describe("counter "));
        println("final=", c.hits);
    }
}

@pure
fn scaled(xs: Int[], k: Int) -> Int[] {
    let out: Int[] = [];
    loop i in 0..length(xs) { out = out + [xs[i] * k]; }
    ret out;
}
fn main() -> Void {
    let base: Int[] = [1, 2, 3];
    let big: Int[] = scaled(base, 10);
    let bigger: Int[] = scaled(big, 3);
    fx {
        print("scaled:");
        loop i in 0..length(big) { print(" ", big[i]); }
        println("");
        print("twice:");
        loop i in 0..length(bigger) { print(" ", bigger[i]); }
        println("");
        print("original:");
        loop i in 0..length(base) { print(" ", base[i]); }
        println("");
    }
}

