@pure
fn splitOn(s: Text, sep: Text) -> Text[] {
    let out: Text[] = [];
    let start: Int = 0;
    loop i in 0..string_len(s) {
        if s[i..i + 1] == sep {
            out = out + [s[start..i]];
            start = i + 1;
        }
    }
    out = out + [s[start..string_len(s)]];
    ret out;
}
@pure
fn upperFirst(s: Text) -> Text {
    if string_len(s) == 0 { ret s; }
    ret upcase(s[0]) + s[1..string_len(s)];
}
fn main() -> Void {
    let parts: Text[] = splitOn("red-green-blue", "-");
    fx {
        loop i in 0..length(parts) {
            println(i, ":", upperFirst(parts[i]), " len=", string_len(parts[i]));
        }
        println("count=", length(parts));
    }
}

const READ: Int = 1;
const WRITE: Int = 2;
const EXEC: Int = 4;
@pure
fn describe(flags: Int) -> Text {
    let out: Text = "";
    if (flags & READ) != 0 { out = out + "r"; } else { out = out + "-"; }
    if (flags & WRITE) != 0 { out = out + "w"; } else { out = out + "-"; }
    if (flags & EXEC) != 0 { out = out + "x"; } else { out = out + "-"; }
    ret out;
}
fn main() -> Void {
    let modes: Int[] = [0, 1, 3, 5, 7, 6];
    let total: Int = 0;
    fx {
        loop i in 0..length(modes) {
            println(modes[i], " -> ", describe(modes[i]));
        }
    }
    loop i in 0..length(modes) { total = total | modes[i]; }
    fx { println("union=", total, " shifted=", total << 2); }
}

tasks.prompt:
Write an Aether program that reads `fleet.json` with the TOON reader and rolls up the `fleet` array. The file is already present in the working directory and contains exactly:

    {"fleet":[{"id":"a1","spec":{"cores":8,"mem":{"gb":32}},"tags":["prod"]},{"id":"b2","spec":{"cores":4},"tags":[]},{"id":"c3","spec":{"cores":16,"mem":{"gb":128}},"tags":["prod","gpu"]}]}

For each entry print `<id>: cores=<n> mem=<n> tags=<n>`. Note that BOTH `cores` and `mem` live under the entry's `spec` object -- `cores` is `spec.cores` and `mem` is `spec.mem.gb` -- and the `mem` intermediate is ABSENT on some entries. A defaulted getter only protects the final lookup, not the path to it, so make the path safe and use 0 when `mem` is missing. `tags` is the length of that entry's tags array. Then print `totals cores=<n> mem=<n> tagged=<count of entries with at least one tag>`.

tasks.reference_solution:
fn main() -> Void {
    let doc: ToonDoc;
    fx { doc = toon_parse_file("fleet.json"); }
    let root: ToonNode = toon_root(doc);
    let fleet: ToonNode = toon_key(root, "fleet");
    let totalCores: Int = 0;
    let totalMem: Int = 0;
    let tagged: Int = 0;
    fx {
        loop i in 0..toon_len(fleet) {
            let node: ToonNode = toon_at(fleet, i);
            let id: Text = toon_get_text_or(node, "id", "?");
            let spec: ToonNode = toon_key(node, "spec");
            let cores: Int = toon_get_int_or(spec, "cores", 0);
            let memGb: Int = 0;
            if toon_has_key(spec, "mem") {
                let mem: ToonNode = toon_key(spec, "mem");
                memGb = toon_get_int_or(mem, "gb", 0);
            }
            let tags: ToonNode = toon_key(node, "tags");
            let ntags: Int = toon_len(tags);
            totalCores = totalCores + cores;
            totalMem = totalMem + memGb;
            if ntags > 0 { tagged = tagged + 1; }
            println(id, ": cores=", cores, " mem=", memGb, " tags=", ntags);
        }
        println("totals cores=", totalCores, " mem=", totalMem, " tagged=", tagged);
        toon_close(doc);
    }
}

@pure
fn minMax(xs: Int[]) -> (Int, Int) {
    let lo: Int = xs[0];
    let hi: Int = xs[0];
    loop i in 1..length(xs) {
        if xs[i] < lo { lo = xs[i]; }
        if xs[i] > hi { hi = xs[i]; }
    }
    ret (lo, hi);
}
@pure
fn sumCount(xs: Int[]) -> (Int, Int) {
    let s: Int = 0;
    loop i in 0..length(xs) { s = s + xs[i]; }
    ret (s, length(xs));
}
fn main() -> Void {
    let data: Int[] = [12, 5, 30, 8, 21];
    let (lo, hi) = minMax(data);
    let t = sumCount(data);
    let total: Int = t.0;
    let n: Int = t.1;
    let mean: Real = total / n;
    fx {
        println("lo=", lo, " hi=", hi, " span=", hi - lo);
        println("sum=", total, " n=", n, " mean=", formatfloat(mean, 2));
        println("floorMean=", trunc(mean));
    }
}

fn main() -> Void {
