        println("bytes=", string_len(body), " fields=", length(fields));
        println("name=", name, " qty=", qty, " doubled=", qty * 2);
    }
}

type Line { label: Text = ""; cents: Int = 0; }
@pure
fn asMoney(cents: Int) -> Text {
    let whole: Int = cents / 100;
    ret formatfloat(cents / 100.0, 2);
}
fn main() -> Void {
    let items: Line[] = [];
    items = items + [new Line { label: "widget", cents: 1999 }];
    items = items + [new Line { label: "gadget", cents: 550 }];
    items = items + [new Line { label: "bolt", cents: 7 }];
    let total: Int = 0;
    fx {
        loop i in 0..length(items) {
            println(items[i].label, ": ", asMoney(items[i].cents));
        }
    }
    loop i in 0..length(items) { total = total + items[i].cents; }
    let avg: Real = total / length(items);
    fx {
        println("total=", asMoney(total));
        println("avg=", formatfloat(avg / 100.0, 3), " rounded=", round(avg));
    }
}

@pure
fn indexOf(keys: Text[], key: Text) -> Int {
    loop i in 0..length(keys) {
        if string_eq(keys[i], key) { ret i; }
    }
    ret -1;
}
fn main() -> Void {
    let keys: Text[] = [];
    let counts: Int[] = [];
    let words: Text[] = ["ash", "birch", "ash", "cedar", "birch", "ash"];
    loop i in 0..length(words) {
        let at: Int = indexOf(keys, words[i]);
        if at == -1 {
            keys = keys + [words[i]];
            counts = counts + [1];
        } else {
            counts[at] = counts[at] + 1;
        }
    }
    let bestAt: Int = 0;
    loop i in 1..length(keys) {
        if counts[i] > counts[bestAt] { bestAt = i; }
    }
    fx {
        loop i in 0..length(keys) { println(keys[i], "=", counts[i]); }
        println("distinct=", length(keys));
        println("most=", keys[bestAt], " (", counts[bestAt], ")");
    }
}
